formulas.expression:
IF(
  ISBLANK(BLANKVALUE({!getContractFinal.EndDate}, {!getContractFinal.Warranty_End_Date__c})),
  {!getContractLineItem.EndDate},
  IF(
    ISBLANK({!getContractLineItem.EndDate}),
    BLANKVALUE({!getContractFinal.EndDate}, {!getContractFinal.Warranty_End_Date__c}),
    IF(
      BLANKVALUE({!getContractFinal.EndDate}, {!getContractFinal.Warranty_End_Date__c}) < {!getContractLineItem.EndDate},
      BLANKVALUE({!getContractFinal.EndDate}, {!getContractFinal.Warranty_End_Date__c}),
      {!getContractLineItem.EndDate}
    )
  )
)

IF(
  ISBLANK(BLANKVALUE({!getContractFinal.StartDate}, {!getContractFinal.Warranty_Start_Date__c})),
  {!getContractLineItem.StartDate},
  IF(
    ISBLANK({!getContractLineItem.StartDate}),
    BLANKVALUE({!getContractFinal.StartDate}, {!getContractFinal.Warranty_Start_Date__c}),
    IF(
      BLANKVALUE({!getContractFinal.StartDate}, {!getContractFinal.Warranty_Start_Date__c}) < {!getContractLineItem.StartDate},
      BLANKVALUE({!getContractFinal.StartDate}, {!getContractFinal.Warranty_Start_Date__c}),
      {!getContractLineItem.StartDate}
    )
  )
)
